import re, json, os

# Detection hints from breaking-changes.json
hints = {
    "BC-001": r"from pydantic import (.*\bBaseSettings\b|BaseSettings)",
    "BC-002": r"@(validator|root_validator)\b",
    "BC-003": r"class Config\s*:",
    "BC-004": r"Field\s*\([^)]*\b(regex|min_items|max_items|const|unique_items)\s*=",
    "BC-005": r"\.(dict|json|copy|schema|parse_obj|parse_raw|construct)\s*\(|\.__fields__\b",
    "BC-006": r"pytest\.raises\s*\(\s*TypeError\s*\)",
}

# Files to scan
scan_files = [
    "src/uplift_demo/models.py",
    "src/uplift_demo/service.py",
    "src/uplift_demo/settings.py",
    "tests/test_models.py",
    "tests/test_service.py",
    "tests/test_uplift_orchestrator.py",
]

usage_map = {bc_id: [] for bc_id in hints}

for filepath in scan_files:
    with open(filepath, encoding="utf-8") as f:
        lines = f.readlines()
    for lineno, raw_line in enumerate(lines, start=1):
        line = raw_line.rstrip("\n")
        for bc_id, pattern in hints.items():
            if re.search(pattern, line):
                usage_map[bc_id].append({
                    "file": filepath,
                    "line": lineno,
                    "snippet": line
                })

# Print a summary
for bc_id, hits in usage_map.items():
    print(f"{bc_id}: {len(hits)} hit(s)")
    for h in hits:
        print(f"  {h['file']}:{h['line']}  {h['snippet'].strip()}")

